  await assertLastOwnerRetained(input.orgId, input.memberId, "member");

  const removed = await memberRepo.archiveMember(input.orgId, input.memberId);

  await emit("member.removed", {
    ...actorEnvelope(actor),
    memberId: removed.id,
    userId: removed.userId,
  });

  return removed;
}

/** Thrown when work is handed to a suspended member. */
export class MemberSuspendedError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly memberId: MemberId) {
    super(`Member ${memberId} is suspended and cannot take on new work`);
    this.name = "MemberSuspendedError";
  }
}

/**
 * Locks a member out without removing them: they keep their membership, role
 * and seat, but can no longer act, receive notifications or be handed new
 * work until `reinstateMember` reverses it.
 */
export async function suspendMember(
  actor: Actor,
  input: SuspendMemberInput,
): Promise<Member> {
  assertOrgScope(actor, input.orgId);

  const member = await requireLiveMember(input.orgId, input.memberId);
  assertCan(actor, "member:remove", memberResource(member));
  assertMaySuspendOrReinstate(actor, member);

  if (member.status === "suspended") return member;

  await assertLastOwnerRetained(input.orgId, input.memberId, "member");

  const suspended = await memberRepo.setMemberStatus(
    input.orgId,
    input.memberId,
    "suspended",
  );

  await emit("member.suspended", {
    ...actorEnvelope(actor),
    memberId: suspended.id,
    userId: suspended.userId,
  });

  return suspended;
}

/** Reverses a suspension; a no-op, publishing nothing, if already active. */
export async function reinstateMember(
  actor: Actor,
  input: ReinstateMemberInput,
): Promise<Member> {
  assertOrgScope(actor, input.orgId);

  const member = await requireLiveMember(input.orgId, input.memberId);
  assertCan(actor, "member:remove", memberResource(member));
  assertMaySuspendOrReinstate(actor, member);

  if (member.status === "active") return member;

  const reinstated = await memberRepo.setMemberStatus(
    input.orgId,
    input.memberId,
    "active",
  );

  await emit("member.reinstated", {
    ...actorEnvelope(actor),
    memberId: reinstated.id,
    userId: reinstated.userId,
  });

  return reinstated;
}

/** A member id must resolve inside the org and must not already be removed. */
async function requireLiveMember(
  orgId: OrgId,
  memberId: MemberId,
): Promise<Member> {
  const member = await memberRepo.findMemberById(orgId, memberId);
  if (!member || member.archivedAt !== null) {
    throw new NotFoundError("Member", memberId);
  }
  return member;
}

/**
 * Neither suspending nor reinstating may target yourself or a member whose
 * role outranks the actor's — an admin cannot suspend an owner, but an owner
 * may suspend anyone.
 */
function assertMaySuspendOrReinstate(actor: Actor, member: Member): void {
  if (member.userId === actor.userId) {
    throw new Error("You cannot suspend or reinstate yourself");
  }
  if (!hasRoleAtLeast(actor.role, member.role)) {
    throw new Error(
      `A ${actor.role} cannot suspend or reinstate a ${member.role}`,
    );
  }
}

/**
 * Turns a (user, org) pair into the `Actor` every service method takes. The
 * only place an `Actor` is minted from stored state — jobs and the session
 * layer both come through here.
 */
export async function resolveActor(
  userId: UserId,
  orgId: OrgId,
): Promise<Actor | null> {
  const member = await memberRepo.findMember(orgId, userId);
  if (!member || member.status !== "active") return null;

  return { userId, orgId, role: member.role };
}

/**
 * Throws when applying `nextRole` to `memberId` would leave the organization
 * without an owner. Exported because the demote, remove and suspend paths all
 * need it, and the invariant must not be stated twice. A suspended owner does
 * not keep the workspace ownable, so only active owners count as "remaining".
 */
export async function assertLastOwnerRetained(
  orgId: OrgId,
  memberId: MemberId,
  nextRole: Role,
): Promise<void> {
  if (nextRole === "owner") return;

  const member = await memberRepo.findMemberById(orgId, memberId);
  if (!member || member.role !== "owner") return;

  const page = await memberRepo.listMembers({
    orgId,
    role: "owner",
    limit: OWNER_SCAN_LIMIT,
    cursor: null,
  });

  const remaining = page.items.filter(
    (row) => row.id !== memberId && row.status === "active",
  );
  if (remaining.length === 0) {
    throw new Error(
      "An organization must keep at least one owner; transfer ownership first",
    );
  }
}

